import{_ as s,o as a,c as t,a5 as e}from"./chunks/framework.BEZBAInb.js";const g=JSON.parse('{"title":"シンタックスハイライター","description":"","frontmatter":{"title":"シンタックスハイライター","order":5},"headers":[],"relativePath":"ja/2.4/tutorial/core/ks-editor-highlighter.md","filePath":"ja/2.4/tutorial/core/ks-editor-highlighter.md","lastUpdated":1788455378000}'),h={name:"ja/2.4/tutorial/core/ks-editor-highlighter.md"};function l(n,i,p,r,d,o){return a(),t("div",null,[...i[0]||(i[0]=[e(`<h1 id="knd-kshighlighter-エディターシンタックスハイライト" tabindex="-1">KND_KsHighlighter エディターシンタックスハイライト <a class="header-anchor" href="#knd-kshighlighter-エディターシンタックスハイライト" aria-label="Permalink to &quot;KND_KsHighlighter エディターシンタックスハイライト&quot;">​</a></h1><h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>シンタックスハイライトはエディターの重要な構成要素です。開発者がコード構造を直感的に識別できるようにし、記述効率と可読性を高めます。<br><code>KND_KsHighlighter</code> は Godot エンジンの <code>SyntaxHighlighter</code> を基に実装された、KS スクリプト専用のハイライターです。ハイライト規則を 1 つのスクリプトに集約して定義しているため、カスタマイズと拡張が非常に柔軟です。既存規則を簡単に調整でき、新しい配色方案を追加することもできます。</p><h2 id="基本実装" tabindex="-1">基本実装 <a class="header-anchor" href="#基本実装" aria-label="Permalink to &quot;基本実装&quot;">​</a></h2><p><code>KND_KsHighlighter</code> では、ハイライト規則は配列として保存されます。各配列要素は辞書で、2 つのキーを含みます。</p><ul><li><code>regex</code>：テキストをマッチするための正規表現（Godot の RegEx 構文）。</li><li><code>color</code>：マッチしたテキストの色。<code>Color(r, g, b, a)</code> で表し、<code>a</code> は透明度です（任意、デフォルトは 1.0）。</li></ul><p>構造例：</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	&quot;regex&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">b(if|else|endif)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">b&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	&quot;color&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>ハイライターは配列順に規則をマッチします。後から適用される規則が先のマッチを上書きする場合があるため、規則の順序は重要です。一般的なコマンドを前に、文字列やコメントを後ろに置くことで、上書き効果を適切に保つことを推奨します。</p><h2 id="カスタム配色方案" tabindex="-1">カスタム配色方案 <a class="header-anchor" href="#カスタム配色方案" aria-label="Permalink to &quot;カスタム配色方案&quot;">​</a></h2><p>エディターへカスタムハイライトを適用する方法は 2 つあります。</p><h3 id="方法-1-リソースファイルを変更-推奨" tabindex="-1">方法 1：リソースファイルを変更（推奨） <a class="header-anchor" href="#方法-1-リソースファイルを変更-推奨" aria-label="Permalink to &quot;方法 1：リソースファイルを変更（推奨）&quot;">​</a></h3><p>デフォルトの配色方案はリソースファイルとして以下に保存されています。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>res://addons/konado/editor/ks_editor/ks_syntax_highlighter.tres</span></span></code></pre></div><p>このリソースファイルを直接編集すれば変更を保持でき、毎回再生成する必要がありません。<br> コード内でこのリソースを読み込んで使用します。</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set_syntax_highlighter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">load</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;res://addons/konado/editor/ks_editor/ks_syntax_highlighter.tres&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><h3 id="方法-2-インスタンスを動的に作成" tabindex="-1">方法 2：インスタンスを動的に作成 <a class="header-anchor" href="#方法-2-インスタンスを動的に作成" aria-label="Permalink to &quot;方法 2：インスタンスを動的に作成&quot;">​</a></h3><p>コード内で新しい <code>KND_KsHighlighter</code> インスタンスを直接作成し、カスタム規則を設定することもできます。たとえばスクリプト内の <code>highlight_rules</code> を変更します。</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set_syntax_highlighter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">KND_KsHighlighter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span></code></pre></div><blockquote><p><strong>注意</strong>：<code>KND_KsHighlighter.gd</code> スクリプトを直接変更した場合、変更を反映するにはリソースファイルの再生成が必要になる場合があります。配色をより明確に管理するため、リソースファイル方式を優先することを推奨します。</p></blockquote>`,20)])])}const c=s(h,[["render",l]]);export{g as __pageData,c as default};
